def ddt(lang):
 s=F.start(220)+t(425,30,'Cl',14)+line(425,36,425,52)+t(395,48,'Cl',14)+line(405,52,418,60)+t(455,48,'Cl',14)+line(445,52,432,60)+t(425,70,'C',15)+line(425,76,425,96)+t(425,108,'C',15)+t(440,128,'H',13)+line(428,114,432,118)
 s+=line(415,112,365,130)+F.ring(330,150,32,subs={4:'Cl'})+line(435,112,485,130)+F.ring(520,150,32,subs={2:'Cl'})
 s+=t(425,212,lb(lang,'dichlorodiphenyltrichloroethane (DDT)'),12)
 return s+'</svg>'

add('Chemical Composition of a Dye','رنگ کی کیمیائی ترکیب','د رنګ کیمیاوي ترکیب','heading')
add('A dye consists of a colour producing structure called the ‘chromogen’ and a part to regulate the solubility and dying properties called the ‘auxochrome’. The chromogen is an aromatic body containing a colour-giving group, commonly called the ‘chromosphore’. Chromophore is that part of the molecule which when exposed to visible light will absorb and reflect a certain colour. Some common chromophores are given in the Table 22.1.','رنگ ایک رنگ پیدا کرنے والی ساخت جسے ’کروموجن‘ کہتے ہیں اور حل پذیری اور رنگنے کی خصوصیات منظم کرنے والے حصے جسے ’آکسوکروم‘ کہتے ہیں، پر مشتمل ہے۔ کروموجن ایک ارومیٹک جسم ہے جس میں رنگ دینے والا گروپ ہوتا ہے جسے عموماً ’کروموفور‘ کہتے ہیں۔ کروموفور سالمے کا وہ حصہ ہے جو مرئی روشنی کے سامنے آنے پر ایک خاص رنگ جذب اور منعکس کرتا ہے۔ چند عام کروموفورز جدول 22.1 میں دیے گئے ہیں۔','رنګ له یوه رنګ تولیدوونکي جوړښت چې ’کروموجن‘ بلل کېږي او د حلېدنې او رنګولو د ځانګړنو د تنظیم له یوې برخې چې ’اوکسوکروم‘ بلل کېږي جوړ دی. کروموجن یو اروماتیک جسم دی چې رنګ ورکوونکی ګروپ لري، چې عموماً ’کروموفور‘ بلل کېږي. کروموفور د مالیکول هغه برخه ده چې د لیدلو وړ رڼا سره د مخ کېدو پر مهال یو ټاکلی رنګ جذبوي او منعکسوي. ځینې عام کروموفورونه په جدول 22.1 کې ورکړل شوي.')
